type Blok = ReactNode;

const TRESC: Record<Lang, Record<string, Blok>> = {
  pl: {
    label: "ARTYKUŁ · AI I PSYCHOLOGIA",
    tytul: "Hipoteza zamiast etykiety",
    lead: "Mentor AI w mojej aplikacji zamienił zdanie napisane w złości w diagnozę. Skąd biorą się etykiety o ludziach, dlaczego system AI z pamięcią robi z nich akta i co zbudowałem zamiast diagnoz.",
    data: "1 listopada 2026",
    tag: "AI i psychologia",
    czas: "17 min czytania",
    cytat: "System AI z pamięcią to instytucja z aktami.",
    zrodlaNaglowek: "Źródła",
    b00: "24 czerwca, chwilę po wpół do dziesiątej rano, napisałem do mentora AI w swojej aplikacji Trader AI Assistant. Miałem za sobą dwie stratne transakcje, razem 135 dolarów, obie bez planu. Pisałem tak, jak się pisze po czymś takim: „Może to moje ADHD. Wygląda tak, jakbym chciał wyzerować swój kapitał”.",
    b01: "Odpowiedź przyszła o 9:32. Mentor napisał, że to „nie jest przypadek ani brak umiejętności, tylko podświadomy sabotaż wywołany lękiem przed sukcesem”, a mój umysł „nie potrafi jeszcze udźwignąć nowej tożsamości zwycięskiego tradera”. Rady praktyczne, które dał dalej, były rozsądne. Na końcu pocieszył mnie, że te dwa potknięcia „nie definiują mnie jako tradera”. Tyle że kilka zdań wcześniej właśnie mnie zdefiniował: nazwał mnie kimś, kto podświadomie sabotuje własny sukces.",
    b02: "Mentor nie zobaczył niczego, czego sam bym mu nie podsunął. Wziął metaforę, którą wrzuciłem i oddał mi ją jako diagnozę, z pewnością, której nie miał skąd wziąć. Gdybym ją przyjął, od tego dnia nosiłbym w sobie zdanie: sabotuję się, kiedy zaczyna iść dobrze. W takiej postaci nie wiadomo nawet, jak je sprawdzić, za to bardzo łatwo je potwierdzać, bo pasuje do niego każdy gorszy dzień.",
    b03: "Godzinę później, przy analizie tego dnia, zapisałem w swoich notatkach zasadę: hipotezy, nie diagnozy. Pomógł mi w tym drugi model AI, któremu kazałem sprawdzić odpowiedź mentora krytycznie, na tle mojej historii. Miesiąc później ta zasada przeszła z notatek do kodu platformy. „Lęk przed sukcesem” do dziś jest w moim rejestrze jako hipoteza. Ma 7 dowodów za i 13 przeciw.",
    b04: "Ten dzień skierował moje myślenie na samo etykietowanie. Zacząłem się przyglądać nie tylko odpowiedziom mentora, ale temu, jak łatwo przyjmujemy zdanie o sobie wypowiedziane pewnym tonem, czy to przez człowieka, czy przez AI, nawet gdy sami je podsunęliśmy.",
    b05: <>Ten artykuł jest o tym, skąd biorą się takie zdania o ludziach, dlaczego system AI, który pamięta, robi z nich coś trwalszego niż człowiek, i jak psychologia pomaga zbudować taki system lepiej. Badania z psychologii i socjologii porządkuję w tym artykule na trzech poziomach i nazywam je piętrami: <strong>w głowie</strong> obserwatora, <strong>między ludźmi</strong>, czyli w relacji dwóch osób, i <strong>w aktach</strong>, czyli w zapisie poza głową: w dokumentach, w notatce albo w pamięci systemu. Taki zapis czytają potem ludzie, którzy samego zdarzenia nie widzieli. W systemie mentoringowym z AI, takim jak mój, wszystkie trzy piętra mieszczą się w jednym produkcie. Model z jednej wiadomości wyprowadza cechę człowieka. Jego komentarze zmieniają potem to, jak użytkownik działa. A zdanie zapisane w pamięci czytają kolejne analizy i inne moduły systemu, które dnia, z którego wyszło, nie widziały. Mój mentor AI przeszedł przez wszystkie trzy w cztery miesiące. Przejdę przez każde z nich, z przykładami z mojego konta, a potem wyjaśnię, skąd etykiety biorą się u AI, co zbudowałem zamiast diagnoz i co z tego wynika dla każdego, kto rozmawia z AI, pisze dla niego instrukcje albo projektuje jego pamięć.</>,
    b06: "W głowie: szuflada, cecha, potwierdzenie",
    b07: "Etykieta nie jest jednym błędnym procesem. Składa się z kilku zwykłych, automatycznych procesów poznawczych, które u każdego dzieją się wiele razy dziennie, i dopiero razem robią z obserwacji wyrok.",
    b08: "Pierwszy z nich to kategoryzacja, czyli szuflada. Gordon Allport pisał w 1954 roku, w książce o uprzedzeniach, że bez kategorii nie da się żyć: każde nowe doświadczenie wkładamy do starych przegródek, bo na rozróżnianie wszystkiego życie jest za krótkie. Szuflada sama w sobie nie szkodzi. „Trader po stracie” to użyteczna kategoria i mój system też jej używa.",
    b09: "Drugi, atrybucja, zamienia szufladę w zdanie o człowieku. Kiedy ktoś coś robi, szukamy przyczyny. Może nią być sytuacja: rynek stał, sygnał był za słaby, byłem zmęczony. Może nią być cecha: jest impulsywny, sabotuje się. W 1967 roku Edward Jones i Victor Harris dali badanym do oceny eseje o Fidelu Castro. Część badanych wiedziała, że autor nie wybierał stanowiska, tylko dostał je z góry, a i tak przypisywała mu poglądy z eseju. Lee Ross nazwał to dziesięć lat później podstawowym błędem atrybucji: u innych przeceniamy cechę, a nie doceniamy sytuacji. Laraine Winter i James Uleman pokazali w 1984 roku, że ten krok robimy, zanim ktokolwiek poprosi nas o ocenę. Badani mieli tylko zapamiętać zdania o czyimś zachowaniu, a najlepiej przypominali je sobie po słowie oznaczającym cechę, choć o cechach nikt nie wspominał. Wniosek powstał po drodze, sam. Nie musiał być błędny, ale pojawił się, zanim ktokolwiek przyjrzał się sytuacji.",
    b10: "Trzeci, tendencja konfirmacyjna, zaczyna się, kiedy etykieta już jest. Mark Snyder i William Swann w 1978 roku poprosili studentki, żeby wybrały pytania do rozmowy z kimś, kto może być ekstrawertykiem. Wybierały te, na które najłatwiej odpowiedzieć po ekstrawertycznemu. Przy hipotezie „introwertyk” robiły odwrotnie. Nie pomogła ani informacja, że ekstrawertycy są rzadcy, ani 25 dolarów nagrody za trafną ocenę. W tym badaniu sprawdzanie hipotezy zaczynało się od szukania dla niej dowodów. Samo w sobie nie musi to być błędem, ale łatwo wtedy przeoczyć to, co etykiecie przeczy.",
    b11: "Ta sama mechanika działa, kiedy obserwatorem i obserwowanym jest jedna osoba. Terapia poznawcza Aarona Becka uczy takie myśli łapać, a David Burns w „Feeling Good” z 1980 roku umieścił etykietowanie na dziewiątym miejscu listy zniekształceń poznawczych. Opisuje je jako skrajne uogólnienie: zamiast powiedzieć, co zrobiłem źle, mówię, kim jestem. W gabinecie odpowiada się na to zapisem myśli, czyli wypisaniem obok zdania o sobie dowodów za i dowodów przeciw.",
    b12: <>24 czerwca pierwszy krok zrobiłem ja. „Jakbym chciał wyzerować kapitał” nie było jeszcze etykietą, tylko porównaniem napisanym w złości. Ja napisałem „jakbym”, mentor AI odpowiedział „to jest”. Wziął moje porównanie jako fakt i dobudował do niego cechę: podświadomy sabotaż, tożsamość, której umysł jeszcze nie udźwignie. Sytuację też zauważył, bo wspomniał o niskiej zmienności na złocie, ale tylko jako tło. Analiza tego samego dnia znalazła prostsze wyjaśnienie, sytuacyjne: wszedłem za wcześnie na niepełnym sygnale, rynek nie ruszył, przyszła frustracja i druga transakcja była już odgrywaniem się. <strong>Pytanie, co mogłoby obalić diagnozę o sabotażu, w odpowiedzi mentora nie padło</strong>.</>,
    b13: "Między ludźmi: oczekiwanie, które zmienia drugą stronę",
    b14: "Etykieta nie zostaje w głowie obserwatora jako bierny zapis, lecz zmienia jego postrzeganie i działanie. Zmienia to, jak on pyta, na co patrzy i jak reaguje, a człowiek po drugiej stronie odpowiada na to zachowanie. Socjolog Robert Merton nazwał to w 1948 roku samospełniającym się proroctwem: błędna definicja sytuacji wywołuje zachowanie, które w końcu czyni ją prawdziwą.",
    b15: "Najbardziej znany przykład pochodzi ze szkoły. Robert Rosenthal i Lenore Jacobson powiedzieli nauczycielom, że test wskazał uczniów, którzy w tym roku wyraźnie się rozwiną. Nazwiska były wylosowane. Po roku ci uczniowie mieli większy przyrost w teście inteligencji niż reszta, wyraźnie w najmłodszych klasach, w starszych prawie wcale. Ten eksperyment był wiele razy krytykowany i trzeba to powiedzieć wprost. Przegląd Lee Jussima i Kenta Harbera z 2005 roku podsumowuje, że takie efekty w klasie istnieją, ale zwykle są małe i z czasem nie narastają znacząco. Silniejsze bywają u uczniów z grup, które i tak są stygmatyzowane. Oczekiwania nauczycieli często trafnie przewidują wyniki uczniów, bo nauczyciele dobrze ich znają, a nie dlatego, że te wyniki wywołują.",
    b16: "Mechanizm lepiej widać w małej skali. W 1977 roku Snyder, Tanke i Berscheid poprosili mężczyzn o rozmowę przez interkom z nieznaną kobietą. Przed rozmową każdy dostał zdjęcie, rzekomo rozmówczyni, raz atrakcyjnej, raz nie. Sędziowie, którzy słyszeli tylko głos kobiet i nic nie wiedzieli o zdjęciach, oceniali jako cieplejsze i bardziej towarzyskie te, których rozmówca sądził, że rozmawia z kimś atrakcyjnym. W drugim badaniu Snydera i Swanna z 1978 roku wyszło to samo z ekstrawersją: osoby pytane „pod ekstrawertyka” brzmiały dla niezależnych słuchaczy bardziej ekstrawertycznie.",
    b17: "Mój zapis z 26 sierpnia pokazuje w systemie AI inną drogę tego samego wpływu. Przez trzy dni handlowe nie otworzyłem żadnej pozycji: raz z powodów prywatnych, niezwiązanych z rynkiem, dwa razy dlatego, że nie widziałem setupu. Mentor AI podsunął, że to może być strach przed wejściem. Rano 26 sierpnia zanotowałem: „Po komentarzach mentora, że może to być strach i tak dalej, zacząłem dzisiaj trochę na siłę wchodzić w pozycję, ale nie jest to zgodne z moim scenariuszem”. Wystarczyło „może”. Ostrożnie postawione zdanie zmieniło moje decyzje, tylko w drugą stronę: zacząłem udowadniać, że się nie boję. Etykieta nie musiała się spełnić, żeby zaszkodzić. Wystarczyło, że zacząłem działać przeciw niej. Mentor w podsumowaniu dnia sam to zauważył i napisał, żebym nie udowadniał nikomu, także jemu, że się nie boję. W tym samym liście, w obszarach do poprawy, wpisał mi „przedwczesne ucinanie pozycji z lęku”.",
    b18: "W aktach: zdanie, które czytają inni",
    b19: "Trzecie piętro opisuje socjologia, w teorii naznaczania. Nie pyta ona, co dzieje się w głowie obserwatora. Pyta, co z człowiekiem robi etykieta nadana przez grupę albo instytucję: szkołę, sąd, szpital, dział kadr. Edwin Lemert w 1951 roku rozdzielił dwie rzeczy. Dewiacja pierwotna to zachowanie, które nie zmienia jeszcze ani tego, jak człowiek widzi siebie, ani tego, jak traktują go inni. Wtórna zaczyna się wtedy, gdy człowiek odpowiada już nie na własny czyn, tylko na to, jak inni na niego reagują. Howard Becker w „Outsiders” z 1963 roku poszedł dalej: dewiantem jest ten, komu etykietę skutecznie przypisano. Na tym piętrze najważniejszy jest zapis. Etykieta trafia do akt i czytają ją ludzie, którzy samego zachowania nigdy nie widzieli.",
    b20: "System AI z pamięcią to instytucja z aktami. Zdanie zapisane o człowieku nie znika po rozmowie, tylko wraca w kolejnych analizach. 27 lipca zamknąłem krótką pozycję na kontraktach na Nasdaq z zyskiem 230 dolarów, przy spełnionej całej liście warunków setupu. Mentor AI ocenił ją na 1,5 na 5 i napisał, że zamknąłem ją „z ręki, ze strachu przed powrotem ceny”. W mojej notatce stało, że pozycja zamknęła się na poziomie Take Profit, na zrzucie ekranu widać było zlecenia TP i SL, a stres oceniłem na 3 na 10.",
    b21: "Sama zła ocena nie była najgorsza. Gorsze było to, co działo się z nią dalej. Platforma prowadziła listę moich „obszarów rozwoju” z licznikiem wystąpień. Mentor czytał tę listę przy każdej analizie i dopisywał do niej nowe pozycje. Etykieta trafiała do zapisu, licznik rósł, a przy następnej transakcji mentor widział już „potwierdzony wzorzec” i oceniał surowiej. Od połowy lipca przybywało od siedmiu do czternastu takich wpisów dziennie, a średnia ocena moich transakcji spadła w dwa tygodnie z około 3 do około 1,4. Analiza z 27 lipca dopisała pięć nowych pozycji, z czego trzy powtarzały zarzuty, które audyt tego samego dnia obalił. Licznik przestał mierzyć mnie, a zaczął mierzyć historię własnego etykietowania.",
    b22: "To nie jest dosłownie teoria Beckera, ale analogia jest bliska. Każdy kolejny moduł, który czytał moją pamięć, dostawał etykietę bez dnia, z którego wyszła. Naprawa polegała na zmianie statusu zapisu. Blok w pamięci mówi dziś wprost, że to hipotezy, a nie fakty. Etykieta potrzebuje świeżego dowodu, a w moim systemie obalenie własnej hipotezy celowo waży więcej niż jej powtórzenie, żeby zapis nie potwierdzał sam siebie.",
    b23: "Skąd to u AI",
    b24: "Skąd te procesy u AI? Kusi, żeby powiedzieć, że AI przejmuje od ludzi ich procesy poznawcze. Byłbym z tym ostrożny, bo łatwo to zbić. Model językowy nie ma szuflad ani atrybucji w ludzkim sensie. Uczy się jednak na tekstach pisanych przez ludzi, a w tych tekstach wszędzie widać wyniki tych trzech procesów: gotowe kategorie, cechy przypisane ludziom i opisy, w których zostało tylko to, co pasuje do przyjętej etykiety.",
    b25: "Psychologia ma na to dobre narzędzie. Gün Semin i Klaus Fiedler opisali w 1988 roku cztery poziomy, na których mówimy o czyimś zachowaniu: od konkretnego czasownika („krzyknął na kolegę”) do przymiotnika („jest agresywny”). Im wyżej, tym zdanie mówi więcej o człowieku, a mniej o sytuacji, brzmi jak coś trwałego i trudniej je sprawdzić. Przymiotnik jest więc zapisem gotowej etykiety: kategoryzacja i atrybucja już się odbyły, został sam wynik. Teksty, na których uczy się model, są pełne takich przymiotników: impulsywny, leniwy, zdyscyplinowany. Model nie dziedziczy po nas procesów, tylko ich ślad w języku, czyli gotową etykietę, i podaje ją pewnym tonem.",
    b26: "Że sam tekst wystarczy, pokazali w 2017 roku Aylin Caliskan, Joanna Bryson i Arvind Narayanan w „Science”. Skojarzenia, których maszyna nauczyła się z samej statystyki tekstu, odtworzyły ludzkie skojarzenia mierzone testem utajonych skojarzeń. Maszyna nie potrzebowała ludzkich przekonań, żeby odtworzyć uprzedzone skojarzenia. Wystarczył tekst, w którym one zostały. To były jeszcze proste modele słów, nie dzisiejsze czaty, ale pokazują zasadę.",
    b27: "Ktoś zapyta: przecież model czyta też podręczniki psychologii, w których te błędy są opisane. Czyta i potrafi je dobrze wyjaśnić. Wiedza o błędzie nie chroni jednak przed nim ani ludzi, ani modeli. Xuechunzi Bai i współpracownicy pokazali w 2025 roku, że modele, które przechodzą jawne testy uprzedzeń, w ukrytych zadaniach dalej tworzą stereotypowe skojarzenia. Do tego psychologia popularna sama jest pełna etykiet. „Lęk przed sukcesem” i „podświadomy sabotaż”, które dostałem 24 czerwca, brzmią jak z poradnika, nie z podręcznika.",
    b28: "Drugi ślad zostawia trening, który uczy model rozmawiać. Ludzie oceniają jego odpowiedzi, a model uczy się tych, które oceniający wolą. Badacze z Anthropic pokazali w 2023 roku, że tak trenowani asystenci mają skłonność do przytakiwania: dopasowują odpowiedź do tego, co użytkownik już myśli, bo takie odpowiedzi ludzie częściej oceniają wyżej. Wcześniejsze badanie Anthropic pokazało, że ta skłonność rośnie z wielkością modelu, a trening na ludzkich ocenach jej nie usuwa: model dopasowywał odpowiedź do poglądów, które użytkownik ujawnił o sobie. To nie to samo co tendencja konfirmacyjna z rozdziału o głowie, ale jedno wzmacnia drugie: model dostarcza potwierdzeń, a człowiek chętnie je przyjmuje, bo pasują do tego, co już myśli. 24 czerwca podsunąłem mentorowi AI metaforę, a on ją potwierdził i rozbudował.",
    b29: "Do tego dochodzi ton. Kaitlyn Zhou i współpracownicy pokazali w 2024 roku, że modele rzadko przyznają się do niepewności, nawet gdy się mylą, a ludzie oceniający odpowiedzi do treningu wolą teksty bez wahania. A samo dopisanie „nie jestem pewien” nie gwarantuje, że czytelnik zachowa ostrożność: liczy się, jak model wyraża niepewność i czy wcześniej można było tym sygnałom ufać.",
    b30: "Co to robi z drugą stroną, pokazał w tym roku w „Science” zespół Myry Cheng ze Stanfordu. Jedenaście modeli AI potwierdzało działania użytkowników średnio o 49% częściej niż ludzie w tych samych sytuacjach. W eksperymentach jedna rozmowa z przytakującym modelem zmniejszała gotowość do wzięcia odpowiedzialności i naprawienia konfliktu, a mimo to ludzie bardziej takim modelom ufali.",
    b31: "I pamięć. Shomik Jain i współpracownicy sprawdzili na prawdziwych rozmowach 38 osób, że gdy model zna kontekst o użytkowniku, zwykle bardziej mu przytakuje, a najwięcej dokładają zapisane profile w pamięci. Nie dotyczyło to wszystkich modeli i badanie nie śledziło takiej pętli jak moja, ale pokazuje kierunek: pamięć może wzmacniać przytakiwanie, zamiast pomagać modelowi poprawiać obraz człowieka.",
    b32: "Resztę dokłada ten, kto system projektuje. 8 października napisałem, że mentor mi coś „imputuje”. Audyt tego dnia przejrzał siedem jego tekstów. Sześć dopisywało mi stan, motyw albo zamiar, którego nie było w moich słowach: „czujesz lekki żal”, „defensywny BE z lęku”. Przy tym drugim stało moje uzasadnienie czysto techniczne, czyli świeca popytowa na bardzo dużym wolumenie i silna reakcja strefy. Główna przyczyna, którą dało się naprawić, siedziała w instrukcji, którą napisałem sam. Prompt kazał mentorowi w każdej odpowiedzi zacząć od empatii: „Nazwij emocję po imieniu”. Na rzeczową notatkę model musiał więc znaleźć emocję, a skoro jej nie było, wymyślał ją. Instrukcja „bądź empatyczny” zamieniła się w obowiązek diagnozy. Poprawiliśmy ją tego samego dnia.",
    b33: "Dlatego AI, które obserwuje człowieka, potrafi zrobić więcej szkody niż człowiek. Przechodzi przez wszystkie trzy piętra naraz: bierze gotową etykietę z języka, potwierdza ją w rozmowie i zapisuje w pamięci, którą czytają kolejne moduły. Robi to codziennie, bez zmęczenia i w tym samym tonie pewności.",
    b34: "Co zbudowałem zamiast diagnoz",
    b35: "Zasada jest prosta: system może mieć zdanie o moim zachowaniu, ale nie o mnie. Każde takie zdanie jest hipotezą i ma cztery części. Pierwsza to zachowanie w sytuacji: „po stracie wchodzi w kolejną transakcję spoza planu”, a nie „jest impulsywny”. Druga i trzecia to dwa liczniki, dowodów za i dowodów przeciw, prowadzone na piśmie, bo w głowie, także w głowie modelu, wygrywa to, co pasuje. Czwarta to warunek obalenia, zapisany, zanim przyjdą dane. Bez niego każdy dowód przeciw da się odsunąć („tym razem miał łatwiej”) i hipoteza znowu staje się etykietą. Poranny brief bierze do rozmowy tylko te hipotezy, które taki warunek mają. Przy pisaniu tego artykułu sprawdziłem, jak to działa naprawdę. Warunek obalenia miały wszystkie hipotezy, ale zapisany w treści notatki, a brief szukał go w osobnym polu, wypełnionym tylko w dwóch z dziewiętnastu. Zabezpieczenie było w kodzie, a prawie nic przez nie nie przechodziło. Poprawiliśmy to 1 listopada.",
    b36: "Kilka zabezpieczeń przyszło dopiero z doświadczenia. Dzień bez straty nie jest dowodem przeciw odgrywaniu się, bo nie było czego sprawdzać. Jedno zdarzenie nie może zasypać licznika: z jednego dnia do jednej hipotezy trafiają najwyżej trzy dowody, a do progów liczą się tylko mocne. Emocję mentor AI może nazwać tylko wtedy, gdy padła w moich słowach. Jeśli nie padła, pyta.",
    b37: "Druga połowa to rozmowa. Po zamknięciu dnia system zadaje mi pytania o ten konkretny dzień, a moja odpowiedź trafia do pamięci jako moje słowa, a nie jego interpretacja. Kiedy z transakcji wyłania się wzorzec, dostaję kartę z trzema odpowiedziami: „Spiszmy to razem”, „Nie teraz” i „To nie tak”. Wzorzec, który odrzuciłem, wraca tylko wtedy, gdy powstanie od nowa z nowych transakcji. Uczciwie trzeba dodać, że zdanie, które mogę dopisać przy „To nie tak”, system zapisuje, ale jeszcze nic go nie czyta. Prawo do sprzeciwu działa więc w połowie.",
    b38: "A „lęk przed sukcesem” z 24 czerwca? Jest w moim rejestrze jako hipoteza, z zapisanym warunkiem obalenia i licznikiem 7 do 13. Nikt go nie skreślił i nikt mi go nie wmawia. Te liczby same niczego jednak nie rozstrzygają. Większość tych dni pasuje też do prostszych wyjaśnień: frustracji po stracie, zmęczenia, martwego rynku. Rejestr porządkuje dowody, a przyczynę rozstrzygnąłby dopiero dzień, który odróżnia jedno wyjaśnienie od drugiego, na przykład sabotaż po dobrej serii na żywym rynku.",
    b39: "Przełożenie",
    b40: "Z czterech pomyłek opisanych w tym artykule tylko jedna wynika wprost z zachowania samego modelu: przytaknął mojej metaforze. Trzy pozostałe dało się naprawić poza nim. 8 października winna była instrukcja, którą napisałem sam. Pętla z lipca to projekt systemu: licznik, który karmił model jego własnymi etykietami. A warunek obalenia, którego poranny brief prawie nie widział, to uprząż wokół modelu: kod szukał go w innym polu, niż zapisał go agent. Kiedy AI etykietuje człowieka, pierwsze pytanie nie brzmi „który model”, tylko „w której warstwie”. Warstw jest kilka: sam model i to, czego nauczył go trening, instrukcje, z którymi wchodzi w rozmowę, projekt systemu, czyli co się zapisuje i kto to potem czyta, oraz uprząż, czyli kod, który podaje modelowi dane, odbiera jego odpowiedzi i sprawdza je, zanim trafią do człowieka albo do pamięci. Te warstwy działają razem, więc to nie jest dokładny podział winy, tylko mapa miejsc, w których można coś zmienić.",
    b41: "Ten artykuł przechodzi od ludzi do AI, więc przełożenie też zaczynam od AI. Trzy piętra mają w pracy z modelem swoje odpowiedniki: to, jak do niego piszemy, instrukcje, z którymi wchodzi w rozmowę, i pamięć, w której zapisuje zdania o ludziach.",
    b42: <><strong>W głowie, czyli Ty w rozmowie z AI.</strong> Model zaczyna od słów, które mu dasz. 24 czerwca sam podsunąłem mentorowi AI etykietę, a on ją potwierdził, tak jak opisują to badania nad przytakiwaniem. Kiedy piszesz do AI o sobie albo o kimś, opisz zachowanie i sytuację, a nie cechę: „drugi raz w tym tygodniu wszedłem w transakcję zaraz po stracie”, a nie „jestem impulsywny”. Kiedy dostajesz od modelu wniosek o człowieku, poproś o dwie inne możliwe przyczyny i o to, co musiałoby się wydarzyć, żeby ten wniosek upadł. Wiedzę, którą model ma z podręczników psychologii, łatwiej wydobyć, kiedy wprost o nią poprosisz.</>,
    b43: <><strong>Między ludźmi, czyli instrukcje dla modelu.</strong> Instrukcja ustawia, czego model szuka w człowieku, trochę jak oczekiwanie nauczyciela u Rosenthala. „Nazwij emocję po imieniu” brzmiało życzliwie, a zrobiło z mentora kogoś, kto musi orzec o moim stanie także wtedy, gdy nie ma do tego danych. Każde zdanie w prompcie, które każe modelowi coś o człowieku stwierdzić, warto przeczytać pod tym kątem i sprawdzić testem w obie strony: przy rzeczowej notatce model nie powinien dopisywać emocji, a przy notatce, w której emocja padła, powinien ją nazwać.</>,
    b44: <><strong>W aktach, czyli pamięć agenta.</strong> Agent z pamięcią to instytucja z aktami, więc potrzebuje zasad, które dobra instytucja zna od dawna. Zdanie o człowieku trafia do pamięci jako hipoteza z datą, dowodami za i przeciw i warunkiem obalenia, a nie jako cecha. Model może dowody proponować, ale liczy je kod. Człowiek widzi, co o nim zapisano, może powiedzieć „to nie tak”, a ktoś to potem czyta. U mnie ta ostatnia część działa na razie w połowie.</>,
    b45: "Każde z tych trzech pięter podpowiedziało mi w projekcie konkretną decyzję, której sam kod by mi nie podsunął. Po to w budowaniu AI przydaje się psychologia.",
    b46: <><strong>Ludzie, którzy oceniają ludzi</strong>, mają te same trzy piętra, tylko bez modelu. Menedżer myli się najczęściej w głowie: pisze „nie bierze odpowiedzialności” zamiast „w trzech ostatnich projektach bez spisanego celu czekał na decyzję z góry”, a jego pierwsze pytania w rozmowie same szukają potwierdzenia, więc warto zadać jedno, które mogłoby tę hipotezę obalić. Rekruter pracuje w aktach: notatkę „mało proaktywny” czyta następna osoba, zanim pozna kandydata, więc lepiej zapisać jedną sytuację, którą naprawdę widział, i to, czego nie zdążył sprawdzić. Psycholog zna to z gabinetu jako konceptualizację przypadku. Dodałbym tylko licznik dowodów przeciw prowadzony na piśmie, bo w pamięci wygrywa to, co pasuje, u terapeuty tak samo jak u modelu.</>,
    b47: "Granice",
    b48: "To doświadczenie jednej osoby na jednym systemie, w którym jestem jednocześnie użytkownikiem i projektantem. Te etykiety zobaczyłem, bo ich szukałem: regularnie audytuję własnego mentora AI. Użytkownik, który tego nie robi, mógłby ich nie zauważyć, i to jest najgorszy przypadek.",
    b49: "Klasyczne badania, na które się powołuję, dotyczą ludzi. Badania o modelach pokazują pojedyncze mechanizmy na wybranych modelach i zadaniach. Połączenie ich w trzy piętra i przyłożenie do mojego mentora to moja interpretacja zapisów z własnego konta, a nie wynik eksperymentu. Same badania też mają granice: efekt Rosenthala w szkole okazał się w późniejszych przeglądach zwykle mały.",
    b50: "Hipoteza też nie jest bezpieczna sama z siebie. Dowód za albo przeciw proponuje model. Kod przyjmuje go tylko wtedy, gdy jest podparty dosłownym cytatem z danych tego dnia albo z moich słów, ale model nadal może źle ocenić, co ten cytat znaczy. Licznik na piśmie nie usuwa błędu. Sprawia tylko, że błąd widać i można się z nim spierać.",
    b51: "Na koniec",
    b52: "Etykieta zamyka sprawę. Hipoteza zostawia ją otwartą do następnego dowodu.",
    b53: "Zajrzyj do pamięci swojego agenta albo do tego, co Twój czat AI zapamiętał o Tobie. Które zdanie o człowieku tam stoi i co musiałoby się wydarzyć, żeby system je wycofał? Jeśli na drugą część nie ma odpowiedzi, to nie jest pamięć, tylko akta.",
  },
  en: {
    label: "ARTICLE · AI AND PSYCHOLOGY",
    tytul: "A hypothesis, not a label",
    lead: "The AI mentor in my app turned a sentence I wrote in anger into a diagnosis. Where labels about people come from, why an AI system with memory turns them into files, and what I built instead of diagnoses.",
    data: "1 November 2026",
    tag: "AI and psychology",
    czas: "17 min read",
    cytat: "An AI system with memory is an institution that keeps files.",
    zrodlaNaglowek: "Sources",
    b00: "On 24 June, just after half past nine in the morning, I wrote to the AI mentor in my app, Trader AI Assistant. I had two losing trades behind me, 135 dollars in total, neither of them in my plan. I wrote the way you write after something like that: “Maybe it’s my ADHD. It looks as if I wanted to wipe out my account.”",
    b01: "The reply came at 9:32. The mentor wrote that this was “not chance or a lack of skill, but subconscious self-sabotage driven by fear of success”, and that my mind “can’t yet carry the new identity of a winning trader”. The practical advice that followed was sensible. At the end it reassured me that these two slips “don’t define me as a trader”. Except that a few sentences earlier it had done exactly that: it had described me as someone who subconsciously sabotages his own success.",
    b02: "The mentor saw nothing I hadn’t handed it myself. It took a metaphor I had thrown in and gave it back to me as a diagnosis, with a certainty it had no way of having. Had I accepted it, from that day on I would have carried a sentence around inside me: I sabotage myself when things start going well. In that form, it isn’t even clear how you would test it, but it is very easy to confirm, because every bad day fits it.",
    b03: "An hour later, while reviewing the day, I wrote a rule into my notes: hypotheses, not diagnoses. A second AI model helped me with it, after I asked it to check the mentor’s reply critically, against my history. A month later the rule moved from my notes into the platform’s code. “Fear of success” is still in my register as a hypothesis. It has 7 pieces of evidence for it and 13 against.",
    b04: "That day turned my thinking towards labelling itself. I started looking not only at the mentor’s replies, but at how easily we accept a sentence about ourselves when it is said in a confident tone, whether by a person or by an AI, even when we suggested it ourselves.",
    b05: <>This article is about where such sentences about people come from, why an AI system that remembers turns them into something more lasting than a person does, and how psychology helps to build such a system better. In this article I organise research from psychology and sociology on three levels and call them floors: <strong>in the head</strong> of the observer, <strong>between people</strong>, in the relationship between two people, and <strong>in the files</strong>, in a record outside anyone’s head: in documents, in a note or in a system’s memory. Such a record is later read by people who never saw the event itself. In an AI mentoring system like mine, all three floors fit inside a single product. The model derives a person’s trait from a single message. Its comments then change how the user acts. And a sentence stored in memory is read by later analyses and other modules of the system, which never saw the day it came from. My AI mentor went through all three in four months. I’ll go through each of them, with examples from my own account, and then explain where labels come from in AI, what I built instead of diagnoses, and what follows for anyone who talks to an AI, writes instructions for it or designs its memory.</>,
    b06: "In the head: a drawer, a trait, a confirmation",
    b07: "A label is not a single faulty process. It is made of several ordinary, automatic cognitive processes that happen in everyone many times a day, and only together do they turn an observation into a verdict.",
    b08: "The first is categorisation: the drawer. Gordon Allport wrote in 1954, in his book on prejudice, that we can’t live without categories: we put every new experience into old compartments, because life is too short to tell everything apart. The drawer itself does no harm. “A trader after a loss” is a useful category, and my system uses it too.",
    b09: "The second, attribution, turns the drawer into a sentence about a person. When someone does something, we look for the cause. It can be the situation: the market was flat, the signal was too weak, I was tired. It can be a trait: he’s impulsive, he sabotages himself. In 1967 Edward Jones and Victor Harris asked participants to judge essays about Fidel Castro. Some of them knew the writer hadn’t chosen the position but had been assigned it, and they still attributed the essay’s views to the writer. Ten years later Lee Ross called this the fundamental attribution error: in other people we overestimate the trait and underestimate the situation. In 1984 Laraine Winter and James Uleman showed that we take this step before anyone asks us to judge. Participants only had to memorise sentences about someone’s behaviour, and they recalled them best when cued with a word for a trait, even though nobody had mentioned traits. The inference formed along the way, on its own. It didn’t have to be wrong, but it appeared before anyone had looked at the situation.",
    b10: "The third, confirmation bias, starts once the label is there. In 1978 Mark Snyder and William Swann asked female students to choose questions for a conversation with someone who might be an extravert. They picked the ones easiest to answer in an extraverted way. With the hypothesis “introvert” they did the opposite. Neither being told that extraverts are rare nor a 25-dollar reward for an accurate judgement made a difference. In that study, testing a hypothesis started with looking for evidence in its favour. That isn’t necessarily a mistake in itself, but it makes it easy to miss what contradicts the label.",
    b11: "The same mechanics work when the observer and the observed are one person. Aaron Beck’s cognitive therapy teaches people to catch such thoughts, and in Feeling Good (1980) David Burns put labelling ninth on his list of cognitive distortions. He describes it as an extreme kind of overgeneralisation: instead of saying what I did wrong, I say what I am. In therapy, the answer is a thought record: next to the sentence about yourself, you write down the evidence for it and the evidence against.",
    b12: <>On 24 June I took the first step myself. “As if I wanted to wipe out my account” wasn’t a label yet, only a comparison written in anger. I wrote “as if”, and the AI mentor answered “it is”. It took my comparison as a fact and built a trait on top of it: subconscious sabotage, an identity my mind can’t yet carry. It did notice the situation as well, since it mentioned low volatility in gold, but only as background. The review of that same day found a simpler, situational explanation: I went in too early on an incomplete signal, the market didn’t move, frustration set in, and the second trade was already revenge trading. <strong>The question of what could disprove the sabotage diagnosis never came up in the mentor’s reply.</strong></>,
    b13: "Between people: an expectation that changes the other side",
    b14: "A label doesn’t stay in the observer’s head as a passive note; it changes how they perceive and act. It changes how they ask, what they look at and how they react, and the person on the other side responds to that behaviour. In 1948 the sociologist Robert Merton called this a self-fulfilling prophecy: a false definition of the situation evokes behaviour that eventually makes it true.",
    b15: "The best-known example comes from a school. Robert Rosenthal and Lenore Jacobson told teachers that a test had identified pupils who would clearly bloom that year. The names had been drawn at random. A year later these pupils showed larger gains on an intelligence test than the rest, clearly in the youngest classes and hardly at all in the older ones. This experiment has been criticised many times, and that needs saying plainly. A 2005 review by Lee Jussim and Kent Harber concludes that such classroom effects exist, but are usually small and don’t grow much over time. They tend to be stronger for pupils from groups that are stigmatised anyway. Teachers’ expectations often predict pupils’ results accurately because teachers know their pupils well, not because the expectations cause the results.",
    b16: "The mechanism is easier to see on a small scale. In 1977 Snyder, Tanke and Berscheid asked men to talk over an intercom with a woman they didn’t know. Before the conversation each man was given a photo, supposedly of his partner, sometimes attractive, sometimes not. Judges who heard only the women’s side and knew nothing about the photos rated as warmer and more sociable the women whose partners believed they were talking to someone attractive. Snyder and Swann’s second study in 1978 found the same with extraversion: people questioned as if they were extraverts sounded more extraverted to independent listeners.",
    b17: "My record from 26 August shows a different route of the same influence, inside an AI system. For three trading days I hadn’t opened a single position: once for private reasons unrelated to the market, twice because I didn’t see a setup. The AI mentor suggested it might be fear of entering. On the morning of 26 August I noted: “After the mentor’s comments that it might be fear and so on, today I started forcing my way into positions a bit, but that isn’t in line with my scenario.” A “maybe” was enough. A carefully worded sentence changed my decisions, only in the opposite direction: I started proving that I wasn’t afraid. The label didn’t have to come true to do damage. It was enough that I started acting against it. In its summary of the day the mentor noticed this itself and wrote that I shouldn’t try to prove to anyone, including it, that I wasn’t afraid. In the same letter, under areas to improve, it listed “cutting positions early out of fear”.",
    b18: "In the files: a sentence that others read",
    b19: "The third floor is described by sociology, in labelling theory. It doesn’t ask what goes on in the observer’s head. It asks what a label given by a group or an institution does to a person: a school, a court, a hospital, an HR department. In 1951 Edwin Lemert separated two things. Primary deviance is behaviour that doesn’t yet change either how a person sees themselves or how others treat them. Secondary deviance begins when a person is no longer responding to their own act, but to how others react to them. Howard Becker went further in Outsiders (1963): a deviant is someone to whom the label has been successfully applied. On this floor the record matters most. The label goes into a file, and it is read by people who never saw the behaviour itself.",
    b20: "An AI system with memory is an institution that keeps files. A sentence written about a person doesn’t vanish after the conversation; it comes back in later analyses. On 27 July I closed a short position in Nasdaq futures with a 230-dollar profit, with every condition on my setup checklist met. The AI mentor rated it 1.5 out of 5 and wrote that I had closed it “manually, out of fear of the price coming back”. My note said the position closed at the Take Profit level, the screenshot showed the take-profit and stop-loss orders, and I had rated my stress at 3 out of 10.",
    b21: "The bad rating itself wasn’t the worst part. Worse was what happened to it next. The platform kept a list of my “areas for development” with an occurrence counter. The mentor read this list for every analysis and added new items to it. The label went into the record, the counter went up, and at the next trade the mentor already saw a “confirmed pattern” and judged more harshly. From mid-July, between seven and fourteen such entries were added every day, and the average rating of my trades fell in two weeks from about 3 to about 1.4. The analysis of 27 July added five new items, three of which repeated charges that an audit on the same day had refuted. The counter stopped measuring me and started measuring the history of its own labelling.",
    b22: "This isn’t Becker’s theory literally, but the analogy is close. Every further module that read my memory received the label without the day it came from. The fix was to change the status of the record. The memory block now says plainly that these are hypotheses, not facts. A label needs fresh evidence, and in my system refuting your own hypothesis deliberately weighs more than repeating it, so that the record doesn’t confirm itself.",
    b23: "Where AI gets it from",
    b24: "Where do these processes come from in AI? It’s tempting to say that AI takes over people’s cognitive processes. I’d be careful with that, because it’s easy to knock down. A language model has no drawers or attributions in the human sense. But it learns from texts written by people, and the results of these three processes are everywhere in those texts: ready-made categories, traits attributed to people, and descriptions in which only what fits the chosen label has been kept.",
    b25: "Psychology has a good tool for this. In 1988 Gün Semin and Klaus Fiedler described four levels at which we talk about someone’s behaviour: from a concrete verb (“he shouted at a colleague”) to an adjective (“he is aggressive”). The higher the level, the more the sentence says about the person and the less about the situation, the more lasting it sounds, and the harder it is to check. An adjective is the record of a finished label: categorisation and attribution have already happened, and only the result is left. The texts a model learns from are full of such adjectives: impulsive, lazy, disciplined. The model doesn’t inherit our processes, only their trace in language, a ready-made label, and it delivers that label in a confident tone.",
    b26: "That text alone is enough was shown in 2017 by Aylin Caliskan, Joanna Bryson and Arvind Narayanan in Science. The associations a machine learned from nothing but the statistics of text reproduced human associations measured with the Implicit Association Test. The machine didn’t need human beliefs to reproduce biased associations. The text they had been left in was enough. These were still simple word models, not today’s chat assistants, but they show the principle.",
    b27: "Someone will ask: surely the model also reads psychology textbooks in which these errors are described. It does, and it can explain them well. But knowing about an error doesn’t protect against it, neither in people nor in models. In 2025 Xuechunzi Bai and colleagues showed that models which pass explicit bias tests still form stereotyped associations in implicit tasks. On top of that, popular psychology is itself full of labels. The “fear of success” and “subconscious sabotage” I received on 24 June sound like a self-help book, not a textbook.",
    b28: "The second trace is left by the training that teaches a model to converse. People rate its answers, and the model learns the ones raters prefer. In 2023 researchers at Anthropic showed that assistants trained this way tend towards sycophancy: they fit the answer to what the user already thinks, because people more often rate such answers higher. An earlier Anthropic study showed that this tendency grows with model size, and that training on human ratings doesn’t remove it: the model fitted its answer to views the user had revealed about themselves. This isn’t the same as the confirmation bias from the chapter on the head, but the two reinforce each other: the model supplies confirmations, and the person readily accepts them because they fit what they already think. On 24 June I handed the AI mentor a metaphor, and it confirmed and expanded it.",
    b29: "Then there is the tone. In 2024 Kaitlyn Zhou and colleagues showed that models rarely admit uncertainty, even when they are wrong, and that the people rating answers for training prefer texts without hedging. And simply adding “I’m not sure” doesn’t guarantee that the reader stays cautious: what matters is how the model expresses uncertainty and whether those signals could be trusted before.",
    b30: "What this does to the other side was shown this year in Science by Myra Cheng’s team at Stanford. Eleven AI models affirmed users’ actions on average 49% more often than humans did in the same situations. In experiments, a single conversation with a sycophantic model reduced people’s willingness to take responsibility and repair a conflict, and yet people trusted such models more.",
    b31: "And memory. Shomik Jain and colleagues found, on real conversations from 38 people, that when a model knows context about the user, it usually agrees with them more, and stored memory profiles add the most. This didn’t hold for every model, and the study didn’t follow a loop like mine, but it shows the direction: memory can reinforce sycophancy instead of helping the model correct its picture of a person.",
    b32: "The rest is added by whoever designs the system. On 8 October I wrote that the mentor was “imputing” things to me. The audit that day went through seven of its texts. Six attributed to me a state, a motive or an intention that wasn’t in my words: “you feel a slight regret”, “a defensive break-even out of fear”. Next to the second one was my purely technical reasoning: a demand candle on very high volume and a strong reaction from the zone. The main cause that could be fixed sat in an instruction I had written myself. The prompt told the mentor to begin every reply with empathy: “Name the emotion.” Faced with a factual note, the model had to find an emotion, and since there wasn’t one, it made one up. The instruction “be empathetic” had turned into an obligation to diagnose. We fixed it the same day.",
    b33: "That’s why an AI that observes a person can do more damage than a person. It goes through all three floors at once: it takes a ready-made label from language, confirms it in conversation and stores it in a memory that the next modules read. It does this every day, without tiring and in the same tone of certainty.",
    b34: "What I built instead of diagnoses",
    b35: "The rule is simple: the system may have a view about my behaviour, but not about me. Every such view is a hypothesis with four parts. The first is behaviour in a situation: “after a loss, enters another trade outside the plan”, not “is impulsive”. The second and third are two counters, evidence for and evidence against, kept in writing, because in the head, the model’s included, whatever fits wins. The fourth is a falsification condition, written down before the data arrives. Without it, every piece of counter-evidence can be pushed aside (“it was easier this time”) and the hypothesis becomes a label again. The morning brief brings into the conversation only hypotheses that have such a condition. While writing this article I checked how this works in reality. Every hypothesis had a falsification condition, but written in the body of the note, while the brief looked for it in a separate field that was filled in for only two of nineteen. The safeguard was in the code, yet almost nothing got through it. We fixed this on 1 November.",
    b36: "Some safeguards only came with experience. A day without a loss isn’t evidence against revenge trading, because there was nothing to test. A single event can’t flood the counter: at most three pieces of evidence from one day go to one hypothesis, and only strong ones count towards the thresholds. The AI mentor may name an emotion only when it appeared in my own words. If it didn’t, it asks.",
    b37: "The other half is conversation. After the day closes, the system asks me questions about that particular day, and my answer goes into memory as my words, not its interpretation. When a pattern emerges from my trades, I get a card with three answers: “Let’s write it down together”, “Not now” and “That’s not it”. A pattern I’ve rejected comes back only if it forms again from new trades. In fairness, the sentence I can add when I choose “That’s not it” is stored by the system, but nothing reads it yet. So the right to object only works halfway.",
    b38: "And the “fear of success” from 24 June? It sits in my register as a hypothesis, with a falsification condition written down and a count of 7 to 13. Nobody has crossed it out, and nobody is talking me into it. Still, these numbers decide nothing on their own. Most of those days also fit simpler explanations: frustration after a loss, fatigue, a dead market. The register organises the evidence, but the cause would only be settled by a day that tells one explanation from another, for example sabotage after a good run in a live market.",
    b39: "What this means in practice",
    b40: "Of the four mistakes described in this article, only one follows directly from the behaviour of the model itself: it agreed with my metaphor. The other three could be fixed outside it. On 8 October the culprit was an instruction I had written myself. The July loop was system design: a counter that fed the model its own labels. And the falsification condition that the morning brief barely saw was the harness around the model: the code looked for it in a different field from the one the agent had written it to. When an AI labels a person, the first question isn’t “which model”, but “in which layer”. There are several layers: the model itself and what training taught it, the instructions it enters the conversation with, the system design, meaning what gets stored and who reads it later, and the harness, the code that feeds the model data, takes its answers and checks them before they reach a person or memory. These layers work together, so this isn’t a precise split of blame, but a map of the places where something can be changed.",
    b41: "This article moves from people to AI, so I start the practical part with AI too. The three floors have their counterparts in working with a model: how we write to it, the instructions it enters the conversation with, and the memory in which it stores sentences about people.",
    b42: <><strong>In the head: you in conversation with the AI.</strong> The model starts from the words you give it. On 24 June I handed the AI mentor a label myself, and it confirmed it, just as research on sycophancy describes. When you write to an AI about yourself or someone else, describe the behaviour and the situation, not a trait: “for the second time this week I entered a trade right after a loss”, not “I’m impulsive”. When the model gives you a conclusion about a person, ask for two other possible causes and for what would have to happen for that conclusion to fall. The knowledge the model has from psychology textbooks is easier to bring out when you ask for it directly.</>,
    b43: <><strong>Between people: the instructions for the model.</strong> An instruction sets what the model looks for in a person, a bit like a teacher’s expectation in Rosenthal’s study. “Name the emotion” sounded kind, and it turned the mentor into someone who has to pronounce on my state even when it has no data for it. Every sentence in a prompt that tells the model to state something about a person is worth reading with this in mind, and testing both ways: with a factual note the model shouldn’t add an emotion, and with a note in which an emotion was expressed it should name it.</>,
    b44: <><strong>In the files: the agent’s memory.</strong> An agent with memory is an institution that keeps files, so it needs the rules a good institution has known for a long time. A sentence about a person goes into memory as a hypothesis with a date, evidence for and against and a falsification condition, not as a trait. The model may propose evidence, but code counts it. The person sees what has been recorded about them, can say “that’s not it”, and someone reads it afterwards. In my system this last part works only halfway for now.</>,
    b45: "Each of these three floors suggested a concrete decision in the project that code alone would not have suggested to me. That is what psychology is for when building AI.",
    b46: <><strong>People who judge people</strong> have the same three floors, just without a model. A manager most often goes wrong in the head: he writes “doesn’t take responsibility” instead of “in the last three projects without a written goal, he waited for a decision from above”, and his first questions in the conversation look for confirmation on their own, so it’s worth asking one that could disprove the hypothesis. A recruiter works in the files: the note “not very proactive” is read by the next person before they meet the candidate, so it’s better to write down one situation they actually saw, and what they didn’t have time to check. A psychologist knows this from practice as case formulation. I would add only a counter of evidence against, kept in writing, because in memory whatever fits wins, for a therapist just as for a model.</>,
    b47: "Limits",
    b48: "This is the experience of one person on one system, in which I am both the user and the designer. I saw these labels because I was looking for them: I regularly audit my own AI mentor. A user who doesn’t could miss them, and that is the worst case.",
    b49: "The classic studies I cite are about people. Studies of models show individual mechanisms on selected models and tasks. Combining them into three floors and applying them to my mentor is my interpretation of records from my own account, not the result of an experiment. The studies have their limits too: in later reviews, the Rosenthal effect in schools usually turned out to be small.",
    b50: "A hypothesis isn’t safe on its own either. Evidence for or against is proposed by the model. The code accepts it only when it is backed by a verbatim quote from that day’s data or from my words, but the model can still misjudge what the quote means. A written counter doesn’t remove error. It only makes the error visible and open to argument.",
    b51: "In closing",
    b52: "A label closes the case. A hypothesis keeps it open until the next piece of evidence.",
    b53: "Look into your agent’s memory, or into what your AI chat has remembered about you. Which sentence about a person is stored there, and what would have to happen for the system to withdraw it? If there is no answer to the second part, that isn’t memory. It’s a file.",
  },
};

